K("Invalidar la caché", d="borrar o actualizar la caché cuando el dato original cambia", u="no mostrar precios o datos viejos",
  mas="Al actualizar un producto en la base, borras su clave (DEL producto:7) para que la próxima lectura traiga el dato nuevo. El TTL es la red de seguridad si se olvida.",
  k=["Invalidar es borrar la caché cuando cambia el dato.", "DEL borra una clave de Redis.", "El TTL limita cuánto puede durar un dato viejo."],
  sit="Cambiaste el precio de un producto en la base, pero la tienda sigue mostrando el precio viejo. ¿Qué te faltó?",
  cod="""DEL producto:7""", h="borra la caché del producto",
  pr=("La orden que borra una clave de Redis es ___ (3 letras)", "del"),
  pr2=("Borrar la caché cuando cambia el dato se llama ___ (10 letras)", "invalidar"),
  ec="guardar en caché sin TTL ni invalidación", out="(integer) 1"),
K("Colas con listas de Redis", d="usar listas de Redis como cola de trabajos sencilla", u="procesar tareas en segundo plano sin otro servicio",
  mas="El productor hace LPUSH trabajos '{...}' y el trabajador espera con BRPOP trabajos 0, que bloquea hasta que haya algo. Para reintentos y confirmaciones, mejor Streams o BullMQ.",
  k=["LPUSH agrega un trabajo a la cola.", "BRPOP espera hasta que haya un trabajo.", "Para reintentos se prefieren Streams."],
  sit="Quieres un trabajador que espere tareas nuevas sin consultar Redis cada segundo. ¿Qué orden bloqueante usas?",
  cod="""LPUSH trabajos '{"correo":"ana@correo.com"}'""", h="agrega un trabajo a la cola",
  pr=("La orden que espera bloqueada un trabajo es ___ (5 letras)", "brpop"),
  pr2=("La orden que agrega al inicio de una lista es ___ (5 letras)", "lpush"),
  ec="consultar la cola en un bucle sin pausa", out="(integer) 1"),
K("Bloqueos distribuidos", d="asegurar que solo un servidor haga cierta tarea a la vez", u="evitar que dos copias del servidor cobren dos veces o envíen dos correos",
  mas="SET bloqueo:cobro:42 <id> NX EX 30 solo funciona si la clave no existe (NX) y vence en 30 s. Al terminar se borra si el valor sigue siendo tu id.",
  k=["NX solo crea la clave si no existe.", "EX hace que el bloqueo venza solo.", "Se borra al terminar si sigue siendo tuyo."],
  sit="Tus 3 servidores ejecutan la misma tarea nocturna y cobran 3 veces. ¿Qué opción de SET usas para que solo uno la haga?",
  cod="""SET bloqueo:cobro:42 srv1 NX EX 30""", h="toma el bloqueo por 30 segundos",
  pr=("La opción de SET que solo crea si no existe es ___ (2 letras)", "nx"),
  pr2=("La opción que hace vencer el bloqueo es ___ (2 letras)", "ex"),
  ec="tomar bloqueos sin vencimiento y dejarlos pegados si el servidor cae", out="OK"),
K("Reglas de seguridad de Firestore", d="reglas que deciden quién puede leer o escribir cada documento", u="que nadie acceda a los datos de otros desde la app",
  mas="match /usuarios/{uid} { allow read, write: if request.auth.uid == uid; } deja a cada usuario solo su documento. Sin reglas, cualquiera con tu configuración web puede leer todo.",
  k=["Las reglas de Firestore deciden quién lee o escribe.", "request.auth.uid es el usuario que inició sesión.", "Sin reglas, cualquiera puede leer los datos."],
  sit="Tu app de Firebase deja que cualquier usuario lea los datos de los demás. ¿Qué configuras?",
  cod="""allow read, write: if request.auth.uid == uid;""", h="permite a cada usuario solo su documento",
  pr=("El usuario que inició sesión en las reglas es request.auth.___ (3 letras)", "uid"),
  pr2=("Para permitir una acción en las reglas se usa ___ (5 letras, en inglés)", "allow"),
  ec="dejar las reglas en modo de prueba en producción", out="(regla publicada)"),
K("Firestore en tiempo real", d="escuchar los cambios de documentos y consultas al instante", u="hacer chats o paneles que se actualizan solos",
  mas="onSnapshot(query(collection(db, \"mensajes\"), orderBy(\"fecha\")), snap => ...) llama a la función con cada cambio. Funciona también sin conexión y sincroniza al volver.",
  k=["onSnapshot escucha cambios en tiempo real.", "La función se llama con cada cambio.", "Firestore sincroniza al recuperar la conexión."],
  sit="Quieres que los mensajes del chat aparezcan solos sin recargar. ¿Qué función de Firestore usas?",
  cod="""onSnapshot(collection(db, "mensajes"), (snap) => console.log(snap.size))""", h="cuenta los mensajes en vivo",
  pr=("La función de tiempo real de Firestore es on___ (8 letras, en inglés)", "snapshot"),
  pr2=("Para ordenar una consulta en Firestore se usa order___ (2 letras, en inglés)", "by"),
  ec="olvidar cancelar el oyente y acumular lecturas que se cobran", out="15"),
K("Claves de partición", d="el campo que decide en qué servidor se guarda cada dato en bases distribuidas", u="repartir bien los datos en Cassandra o DynamoDB",
  mas="En Cassandra, PRIMARY KEY ((cliente), fecha) reparte por cliente y ordena por fecha dentro. Una clave con pocos valores (como el país) crea servidores sobrecargados.",
  k=["La clave de partición decide en qué servidor va el dato.", "Una buena clave tiene muchos valores distintos.", "Dentro de la partición los datos se ordenan."],
  sit="Usaste el país como clave de partición y el 90 % de los datos cayó en un solo servidor. ¿Qué elegiste mal?",
  cod="""CREATE TABLE pedidos (cliente text, fecha timestamp, total int, PRIMARY KEY ((cliente), fecha));""", h="crea una tabla con clave de partición",
  pr=("Una partición con demasiados datos se llama partición ___ (7 letras, en inglés)", "caliente", "hot"),
  pr2=("En DynamoDB, la clave que ordena dentro de la partición es la sort ___ (3 letras, en inglés)", "key"),
  ec="elegir una clave con muy pocos valores distintos", out="(tabla creada)"),
K("Recomendaciones con grafos", d="usar Neo4j para encontrar relaciones como «a quien le gustó esto también…»", u="hacer recomendaciones y redes de amigos",
  mas="MATCH (yo:Usuario {id:1})-[:COMPRO]->(:Producto)<-[:COMPRO]-(otro)-[:COMPRO]->(rec) WHERE NOT (yo)-[:COMPRO]->(rec) RETURN rec, count(*) ORDER BY count(*) DESC encuentra recomendaciones.",
  k=["Los grafos son ideales para recomendaciones.", "Cypher recorre relaciones con flechas.", "Se cuentan los caminos para ordenar recomendaciones."],
  sit="Quieres recomendar productos que compraron personas con compras parecidas a las tuyas. ¿Qué tipo de base facilita esa consulta?",
  cod="""MATCH (a:Usuario {id:1})-[:AMIGO]->(b) RETURN count(b)""", h="cuenta los amigos de un usuario",
  pr=("El lenguaje de consultas de Neo4j es ___ (6 letras)", "cypher"),
  pr2=("En Cypher, las relaciones se escriben entre ___ (9 letras)", "corchetes"),
  ec="hacer recomendaciones con muchos JOIN anidados en SQL", out="12"),
K("Elasticsearch para búsquedas", d="motor de búsqueda con relevancia, tolerancia a errores y filtros", u="hacer el buscador de una tienda o los logs de un sistema",
  mas="Un match con fuzziness: \"AUTO\" tolera errores, los analizadores entienden el español (stemming) y las agregaciones crean filtros por categoría y precio. Se usa junto a la base principal.",
  k=["Elasticsearch ordena los resultados por relevancia.", "fuzziness tolera errores de escritura.", "Se usa junto a la base de datos principal."],
  sit="Tu tienda necesita un buscador con filtros por precio y que entienda «zapato» y «zapatos». ¿Qué motor usas junto a tu base?",
  cod="""GET productos/_search { "query": { "match": { "nombre": { "query": "zapato", "fuzziness": "AUTO" } } } }""", h="busca tolerando errores",
  pr=("La opción de Elasticsearch para tolerar errores es ___ (9 letras, en inglés)", "fuzziness"),
  pr2=("Reducir una palabra a su raíz se llama ___ (8 letras, en inglés)", "stemming"),
  ec="usar Elasticsearch como única base de datos de pedidos", out='{ "hits": { "total": { "value": 8 } } }'),
K("Respaldos de bases NoSQL", d="copias de seguridad automáticas y probadas", u="recuperar los datos ante borrados o fallos",
  mas="Atlas tiene respaldos continuos con restauración a un momento exacto; en servidores propios usa mongodump o snapshots del disco. Redis: copia el archivo RDB/AOF. Prueba restaurar cada cierto tiempo.",
  k=["Los respaldos deben ser automáticos.", "Hay que probar que se pueden restaurar.", "Atlas permite restaurar a un momento exacto."],
  sit="Un compañero borró una colección por error a las 3:15 p. m. ¿Qué función de Atlas recupera los datos de las 3:14?",
  cod="""mongodump --uri "$MONGO_URL" --out respaldo-$(date +%F)""", h="hace un respaldo con la fecha",
  pr=("La restauración a un momento exacto se llama point-in-___ (4 letras, en inglés)", "time"),
  pr2=("Un respaldo que nunca se prueba puede estar ___ (6 letras)", "dañado", "danado"),
  ec="tener respaldos que nunca se han probado restaurar", out="done dumping tienda.productos (320 documents)"),
K("Proyecto final NoSQL", d="una app que combina MongoDB, Redis y buenas prácticas de diseño", u="demostrar que sabes elegir y usar bases NoSQL",
  mas="API de una tienda: MongoDB con esquema validado, índices ESR, agregaciones para reportes y TTL para códigos; Redis para caché, sesiones y límite de peticiones; respaldos y usuarios con rol mínimo.",
  k=["Un buen proyecto combina la base adecuada para cada uso.", "Los índices se diseñan según las consultas.", "La seguridad y los respaldos son parte del proyecto."],
  sit="Quieres mostrar en una entrevista que sabes NoSQL de verdad. ¿Qué construyes?",
  cod="""db.productos.getIndexes().length""", h="cuenta los índices del proyecto",
  pr=("Para caché y sesiones se usa ___ (5 letras)", "redis"),
  pr2=("Para los documentos principales se usa ___ (7 letras)", "mongodb"),
  ec="usar una sola base para todo sin pensar en cada caso", out="4"),
